import { getSQLDate } from '@helpers/dateHelper';

import { mapMedicamentsToFront } from './medicaments.mapper';
import {
  IFirstAidKitAddDTO,
  IFirstAidKitApprove,
  IFirstAidKitApproveDTO,
  IFirstAidKitEditDTO,
  IFirstAidKitSelectedForAdd,
  IFirstAidKitSMedicament,
} from '../@types/firstAidKit.types';

interface BackFirstAidKitMedicament {
  amount: string;
  category: string;
  comment: string;
  contraindications: string;
  date: string;
  deadline: string;
  dosage: string;
  for_use: string;
  form: string;
  form_name: string;
  id: string;
  id_author: string;
  id_hiking: string;
  id_medicament: string;
  medical_group: string;
  name: string;
  medicament_id: string;

  id_assignee: string;
  assignee_name: string;
  assignee_surname: string;
  assignee_photo: string;
  count_for_each: string;
}

export const mapFAKMedicamentToFront = (
  backData: BackFirstAidKitMedicament,
): IFirstAidKitSMedicament => {
  return {
    id: +backData.id,
    medicament: { ...mapMedicamentsToFront(backData), id: +backData.medicament_id },
    amount: +backData.amount,
    comment: backData.comment,
    deadline:
      backData.deadline && backData.deadline !== '0000-00-00' ? new Date(backData.deadline) : null,
    count_for_each: +backData.count_for_each,
    assignee: !backData.id_assignee
      ? null
      : {
          id: +backData.id_assignee,
          name: backData.assignee_name,
          surname: backData.assignee_surname,
          photo: backData.assignee_photo,
        },
  };
};

export const mapHikingFAKApproveToFront = (
  backData: IFirstAidKitApproveDTO,
): IFirstAidKitApprove => {
  return {
    id: +backData.id,
    date: new Date(backData.date),
    position: {
      id: +backData.id_position,
      name: backData.position_name,
    },
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      photo: backData.user_photo,
    },
  };
};

export const mapSelectedMedicamentToAddDTO = (
  idHiking: number,
  sel: IFirstAidKitSelectedForAdd,
): IFirstAidKitAddDTO => {
  return {
    id_hiking: idHiking,
    id_medicament: sel.medicament.id,
    amount: sel.amount,
    deadline: sel.deadline ? getSQLDate(sel.deadline) : '',
    comment: sel.comment,
    id_assignee: sel.assignee ? sel.assignee.id : null,
    count_for_each: sel.count_for_each,
  };
};

export const mapSelectedMedicamentToEditDTO = (
  idHiking: number,
  sel: IFirstAidKitSMedicament,
): IFirstAidKitEditDTO => {
  return {
    ...mapSelectedMedicamentToAddDTO(idHiking, sel),
    id: sel.id,
  };
};
