import { get, handleApiError, post } from '@helpers/httpClient';

import {
  IFirstAidKitApprove,
  IFirstAidKitApproveDTO,
  IFirstAidKitCreateApproveDTO,
  IFirstAidKitDeleteApproveDTO,
  IFirstAidKitSelectedForAdd,
  IFirstAidKitSMedicament,
} from '../@types/firstAidKit.types';
import {
  mapFAKMedicamentToFront,
  mapHikingFAKApproveToFront,
  mapSelectedMedicamentToAddDTO,
  mapSelectedMedicamentToEditDTO,
} from '../mappers/firstAidKit.mapper';

export const getFirstAidKidForHikingAsync = async (id_hiking: number) => {
  const rawData = await get('/ajax/hiking/first_aid_kit/first_aid_kit_list.php', { id_hiking });
  return rawData.map(mapFAKMedicamentToFront);
};

export const addFirstAidKitMedicamentAsync = async (
  id_hiking: number,
  selected: IFirstAidKitSelectedForAdd,
): Promise<number> => {
  const rawData = await post(
    '/ajax/hiking/first_aid_kit/first_aid_kit_add.php',
    mapSelectedMedicamentToAddDTO(id_hiking, selected),
    {},
  );
  if (rawData.error) {
    throw new Error(rawData.error);
  }

  return +rawData.id;
};

export const deleteFirstAidKitMedicamentAsync = async (
  id_hiking: number,
  id: number,
): Promise<void> => {
  const rawData = await post(
    '/ajax/hiking/first_aid_kit/first_aid_kit_del.php',
    { id, id_hiking },
    {},
  );
  if (rawData.error) {
    throw new Error(rawData.error);
  }
};

export const editFirstAidKitMedicamentAsync = async (
  id_hiking: number,
  selected: IFirstAidKitSMedicament,
): Promise<void> => {
  const rawData = await post(
    '/ajax/hiking/first_aid_kit/first_aid_kit_edit.php',
    mapSelectedMedicamentToEditDTO(id_hiking, selected),
    {},
  );
  if (rawData.error) {
    throw new Error(rawData.error);
  }
};

export const getFirstAidKidApproversForHikingAsync = async (
  id_hiking: number,
): Promise<IFirstAidKitApprove[]> => {
  const rawData = await get<IFirstAidKitApproveDTO[]>(
    '/ajax/hiking/first_aid_kit/first_aid_kit_approvers.php',
    { id_hiking },
  ).then(handleApiError);
  return rawData.map(mapHikingFAKApproveToFront);
};

export const setFirstAidKidApproversForHikingAsync = async (
  id_hiking: number,
  id_position: number,
): Promise<number> => {
  const rawData = await post<{ id?: string }, IFirstAidKitCreateApproveDTO>(
    '/ajax/hiking/first_aid_kit/first_aid_kit_set_approve.php',
    { id_hiking, id_position },
  ).then(handleApiError);
  return +rawData?.id;
};

export const deleteFirstAidKidApproversForHikingAsync = async (
  id_hiking: number,
  id: number,
): Promise<boolean> => {
  const rawData = await post<{ success?: boolean }, IFirstAidKitDeleteApproveDTO>(
    '/ajax/hiking/first_aid_kit/first_aid_kit_set_approve_delete.php',
    { id_hiking, id },
  ).then(handleApiError);
  return !!rawData?.success;
};
